mapper.select:
SELECT * FROM com_sales_order
WHERE tenant_id = #{query.tenantId}
  AND source_system = #{query.sourceSystem}
  AND source_record_key = #{query.sourceRecordKey}
  AND deleted = 0
FOR UPDATE

SELECT o.* FROM com_sales_order o WHERE o.tenant_id = #{query.tenantId} AND o.deleted = 0 AND (
CAST(o.company_code AS BINARY) IN
CAST(#{companyCode} AS BINARY)
OR
EXISTS (SELECT 1 FROM com_order_contract_relation ocr JOIN com_project_contract_relation pcr ON pcr.tenant_id = ocr.tenant_id AND pcr.contract_id = ocr.contract_id AND pcr.deleted = 0 AND pcr.status = 'ACTIVE' AND pcr.effective_to IS NULL WHERE ocr.tenant_id = o.tenant_id AND ocr.order_id = o.id AND ocr.deleted = 0 AND pcr.project_id IN
#{projectId} )
)
AND CAST(o.company_code AS BINARY) = CAST(#{query.companyCode} AS BINARY)
AND o.order_no LIKE CONCAT('%', #{query.orderNo}, '%')
AND o.order_type = #{query.orderType}
AND (o.customer_code LIKE CONCAT('%', #{query.customerKeyword}, '%') OR o.customer_name LIKE CONCAT('%', #{query.customerKeyword}, '%'))
AND o.status = #{query.status}
ORDER BY o.order_no, o.id LIMIT #{query.offset}, #{query.limit}
